SELECT *
FROM plans
WHERE delete_flg = 0
  AND user_id = #{user_id}
ORDER BY parent_id ASC NULLS FIRST, sort_order ASC;

SELECT COALESCE(MAX(sort_order), -1) + 1
FROM plans
WHERE user_id = #{user_id}
  AND delete_flg = 0
  AND parent_id = #{parent_id}
  AND parent_id IS NULL
;

